import { existsSync, readdirSync, readFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { describe, expect, it } from 'vitest';

/**
 * Rettich is a context of the Swelper (ADR-0044). Everything under .claude/agents, .claude/skills
 * and .claude/swelper is generated by `swelper sync` from the frame and carries its marker. This
 * test breaks when someone edits a copy by hand or when the set of plugs drifts from the context.
 */
const root = resolve(import.meta.dirname, '..', '..', '..');
const marker = /generated: swelper \d+\.\d+\.\d+/;

function frontmatter(path: string): string {
  const text = readFileSync(path, 'utf8');
  const match = /^---\n([\s\S]*?)\n---\n/.exec(text);
  return match?.[1] ?? '';
}

describe('Swelper: generated files stay generated', () => {
  const agentsDir = join(root, '.claude', 'agents');
  const agents = readdirSync(agentsDir).filter((name) => name.endsWith('.md'));

  it('names the context rettich', () => {
    const settings = JSON.parse(readFileSync(join(root, '.swelper.json'), 'utf8')) as {
      context: string;
    };
    expect(settings.context).toBe('rettich');
  });

  it('marks every agent and skill as generated', () => {
    for (const name of agents) {
      expect(frontmatter(join(agentsDir, name)), name).toMatch(marker);
    }
    const skillsDir = join(root, '.claude', 'skills');
    for (const name of readdirSync(skillsDir)) {
      expect(frontmatter(join(skillsDir, name, 'SKILL.md')), name).toMatch(marker);
    }
  });

  it('has exactly the plugs the context declares', () => {
    const context = JSON.parse(
      readFileSync(join(root, '.claude', 'swelper', 'context.json'), 'utf8'),
    ) as {
      name: string;
      roles: Record<string, unknown>;
    };
    expect(context.name).toBe('rettich');
    expect(agents.map((name) => name.replace(/\.md$/, '')).sort()).toEqual(
      Object.keys(context.roles).sort(),
    );
  });

  it('keeps the standing orders and labels next to the agents', () => {
    for (const name of ['standing-orders.md', 'labels.json']) {
      expect(existsSync(join(root, '.claude', 'swelper', name)), name).toBe(true);
    }
  });
});
